    def parse_fields(fields_str):
        if not fields_str:
            return []
        parts = fields_str.split(",")
        res = []
        for p in parts:
            if "-" in p:
                start_str, end_str = p.split("-")
                start = int(start_str) if start_str else 1
                end = int(end_str) if end_str else None
                res.append((start, end))
            else:
                res.append((int(p), int(p)))
        return res

