                        f_ptr += 1
                for idx in priority_list:
                    if idx not in printed:
                        final_fields.append(idx)
                        printed.add(idx)

                first_line = False

            out_parts = [parts[idx-1] for idx in final_fields if idx <= len(parts)]
            out_f.write(out_delim.join(out_parts) + b"\n")
